  8→static int cpg_copy_trim(char* dst, size_t dst_size, const char* src, int src_len)
  9→{
 10→	if (!dst || dst_size == 0) {
 11→		return -1;
 12→	}
 13→
 14→	dst[0] = '\0';
 15→
 16→	if (!src || src_len <= 0) {
 17→		return 0;
 18→	}
 19→
 20→	int n = src_len;
 21→	while (n > 0 && src[n - 1] == ' ') {
 22→		n--;
 23→	}
 24→
 25→	if ((size_t)n >= dst_size) {
 26→		n = (int)dst_size - 1;
 27→	}
 28→
 29→	memcpy(dst, src, (size_t)n);
 30→	dst[n] = '\0';
 31→	return n;
 32→}
